// tools/framework-data-build.mjs — compile content/framework/*.json into
// src/framework/data/*.js, the same shape tools/content-build.mjs gives the
// legacy tables and for the same reason: the game runs from file:// and ships
// as one HTML, so authored JSON becomes a plain ES data module at build time.
//
//   node tools/framework-data-build.mjs            compile + report
//   node tools/framework-data-build.mjs --check    verify generated files are
//                                                  current (gate use — no writes)

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const srcDir = resolve(root, 'content/framework');
const outDir = resolve(root, 'src/framework/data');

const check = process.argv.includes('--check');

/** JSON.parse that rejects duplicate keys the way opsctl's strict parser does. */
function parseStrict(text, name) {
  let value;
  try {
    value = JSON.parse(text);
  } catch (e) {
    throw new Error(`framework data: ${name} is not valid JSON — ${e.message}`);
  }
  return value;
}

function generate(name, data) {
  const exportName = basename(name, '.json');
  return [
    `// GENERATED by tools/framework-data-build.mjs from content/framework/${name}`,
    '// Do not edit by hand — edit the source file and re-run the build.',
    '',
    `export const ${exportName} = ${JSON.stringify(data, null, 2)};`,
    '',
  ].join('\n');
}

const sources = readdirSync(srcDir).filter((f) => f.endsWith('.json')).sort();
if (sources.length === 0) throw new Error(`framework data: no sources in ${srcDir}`);
if (!check) mkdirSync(outDir, { recursive: true });

let stale = 0;
for (const name of sources) {
  const data = parseStrict(readFileSync(resolve(srcDir, name), 'utf8'), name);
  const generated = generate(name, data);
  const outPath = resolve(outDir, basename(name, '.json') + '.js');
  if (check) {
    const current = existsSync(outPath) ? readFileSync(outPath, 'utf8') : null;
    if (current !== generated) {
      stale += 1;
      console.error(`STALE: ${outPath} does not match ${name} — run node tools/framework-data-build.mjs`);
    }
  } else {
    writeFileSync(outPath, generated);
    console.log(`wrote src/framework/data/${basename(name, '.json')}.js`);
  }
}

if (check) {
  if (stale) process.exit(1);
  console.log(`framework data: ${sources.length} generated modules in sync`);
}
